def _quat_mat(q) -> np.ndarray:
    w, x, y, z = q
    return np.array([[1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
                     [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
                     [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)]])


def _drehung(achse, winkel) -> np.ndarray:
    a = np.asarray(achse, float) / np.linalg.norm(achse)
    k = np.array([[0, -a[2], a[1]], [a[2], 0, -a[0]], [-a[1], a[0], 0]])
    return np.eye(3) + np.sin(winkel) * k + (1 - np.cos(winkel)) * k @ k


def kugeln(daten: dict, q) -> dict:
    """Lage der vier Kugeln im Rumpfsystem (m) aus den Gelenkwinkeln q (Reihenfolge JOINTS)."""
    ergebnis = {}
    for glied, d in daten.items():
        R, p = np.eye(3), np.zeros(3)
        for pos, quat, j, achse, gpunkt in d["kette"]:
            p = p + R @ np.asarray(pos)
            R = R @ _quat_mat(quat)
            g = np.asarray(gpunkt)                     # Drehung um die Achse durch den Gelenkpunkt
            Rj = _drehung(achse, q[j])
            p = p + R @ (g - Rj @ g)
            R = R @ Rj
        ergebnis[glied] = p + R @ np.asarray(d["kugel"])
    return ergebnis


def _kabsch(A, B):
    """R, t mit R·a + t ≈ b (Zeilen = Punkte)."""
    ca, cb = A.mean(axis=0), B.mean(axis=0)
    U, _, Vt = np.linalg.svd((A - ca).T @ (B - cb))
    D = np.diag([1.0, 1.0, np.sign(np.linalg.det(Vt.T @ U.T))])
    R = Vt.T @ D @ U.T
    return R, cb - R @ ca


def sitzpruefung(kugel_lage: dict, mulden: dict, glied: str) -> tuple[bool | None, float, float]:
    """Sitzt `glied` in seiner Mulde? Die anderen drei Kugeln auf ihre Mulden gelegt (Wand-/Weltkoordinaten,
    mulden: Glied → Muldenmitte). → (True/False, oder None wenn die anderen selbst nicht passen; Abstand in m;
    Rest der Anpassung der anderen drei in m). Verfehlt hat das Glied mit dem kleinsten Rest: drei Kugeln lassen sich
    auch mit einer losen darunter oft unter REST_MAX auflegen, dann wirken alle vier verschoben."""
    andere = [g for g in GLIEDER if g != glied]
    A = np.array([kugel_lage[g] for g in andere])
    B = np.array([mulden[g] for g in andere])
    R, t = _kabsch(A, B)
    rest = float(np.max(np.linalg.norm(A @ R.T + t - B, axis=1)))
    abstand = float(np.linalg.norm(R @ kugel_lage[glied] + t - mulden[glied]))
    if rest > REST_MAX:
        return None, abstand, rest
    return abstand <= SITZ_SCHWELLE, abstand, rest


def mulde_im_rumpf(kugel_lage: dict, mulden: dict, glied: str):
    """Lage der Zielmulde des Glieds im Rumpfsystem und die Drehung Rumpf→Wand, aus den drei anderen (sitzenden)
    Kugeln. → (Mulde im Rumpfsystem, R mit Wand = R·Rumpf + t)."""
    andere = [g for g in GLIEDER if g != glied]
    R, t = _kabsch(np.array([kugel_lage[g] for g in andere]), np.array([mulden[g] for g in andere]))
    return R.T @ (np.asarray(mulden[glied]) - t), R



def _entpacken(teile) -> np.ndarray:
    return np.frombuffer(zlib.decompress(base64.b64decode("".join(teile))), dtype=np.float32).astype(float)


class KletterN1V015DeineMamaMove:
    """Gelernter Aufstieg auf N1 aus der Hängestellung, Sprosse für Sprosse bis ganz oben, mit Eingriffen."""

    name = "kletter_n1_v0_15_deine_mama"
    description = "Klettern N1: gelernter Aufstieg bis ganz oben (aus der Hängestellung an den Startgriffen)"
    variants = ("climber",)
    start_pose = "current"
    kp = 400                       # wie beim Lernen
    options = {"sprossen": SPROSSEN_MAX, "eingriffe": True, "nachgreifen": 3, "ausgleich": 1.25, "ausgleich_links": 1.0,
               "weiter": False}
    option_docs = {"sprossen": "so viele Sprossen klettern (1–13)",
                   "eingriffe": "nach jedem Zug Sitz prüfen, Rumpfneigung überwachen; bei Fehler anhalten",
                   "nachgreifen": "so oft einen verfehlten Griff neu versuchen (Schwung zurück, korrigiert neu; die "
                                  "Korrektur gilt dann für denselben Zug jeder weiteren Sprosse)",
                   "ausgleich": "Handzug rechts: Roboter 1.25, Simulator 0.25–0.5; 1 = gemessene Abweichung",
                   "ausgleich_links": "Handzug links: Roboter 1.0, Simulator 0.25–0.5; 1 = gemessene Abweichung",
                   "weiter": "nach einem Halt einschalten: weiterklettern (dieser Zug gilt als gelungen)"}

    def __init__(self) -> None:
        self._plan = _entpacken(_DATEN).reshape(-1, 19)
        self._ziele = self._plan
        self._soll_s1 = _entpacken(_SOLL_NEIGUNG_S1).reshape(-1, 3)
        self._soll_s2 = _entpacken(_SOLL_NEIGUNG_S2).reshape(-1, 3)

    def start(self, obs) -> None:
        staerke = min(2.0, max(0.0, float(self.options.get("ausgleich", 0.0))))
        self._ziele = self._plan + staerke * _entpacken(_AUSGLEICH).reshape(-1, 19)
        links = min(2.0, max(0.0, float(self.options.get("ausgleich_links", 0.0))))
        self._ziele = self._ziele + links * _entpacken(_AUSGLEICH_LINKS).reshape(-1, 19)
        self._vorlauf, self._folge, self._i = VORLAUF_TAKTE, None, 0
        self._halt, self._grund, self._ueber, self._neigung = None, None, 0, []
        self._mulden = {g: np.array(p) for g, p in _MULDEN_START.items()}
        self._einschub, self._einschub_bis, self._gewartet, self._versuche = 0, -1, set(), {}
        self._uebersprungen = None
        self.options["weiter"] = False

    def _zug_am_ende(self, k: int):
        """Takt k der Folge (ohne Angleichen) → (Zugnummer 0–11, Wiederholung der Sprosse 2), wenn dort ein Zug
        endet."""
        g5, l2 = _GRENZEN[5], _GRENZEN[11] - _GRENZEN[5]
        if k <= g5:
            return (_GRENZEN.index(k), 0) if k in _GRENZEN[:6] else None
        r, rest = divmod(k - g5, l2)
        if rest == 0:
            return 11, r - 1
        ende = g5 + rest
        return (_GRENZEN.index(ende), r) if ende in _GRENZEN[6:] else None

    def _soll_neigung(self, k: int):
        g5, l2 = _GRENZEN[5], _GRENZEN[11] - _GRENZEN[5]
        return self._soll_s1[k] if k < g5 else self._soll_s2[(k - g5) % l2]

    def _anhalten(self, q, grund: str):
        self._halt, self._grund = np.array(q), grund
        self.options["weiter"] = False
        print(f"kletter_n1_v0_15_deine_mama ANGEHALTEN: {grund} — weiter: Option „weiter“ einschalten", flush=True)  # auch im Dashboard

    def on_option(self, name, value) -> None:
        """Option „weiter“ nach einem Halt: aus der gehaltenen Stellung ohne Ruck (1 s) zurück in die Folge, der
        angehaltene Zug gilt als gelungen (seine Prüfung entfällt), der Wächter beginnt von vorn."""
        if name != "weiter" or not value or self._halt is None or self._folge is None:
            return
        i = min(self._i, len(self._folge) - 1)
        q0, q1 = np.array(self._halt, float), np.array(self._folge[i], float)
        m = round(1.0 / 0.02)
        self._uebersprungen = self._i - self._angleichen - self._einschub
        self._einschieben([q0 + (q1 - q0) * ((k / m) ** 2 * (3 - 2 * k / m)) for k in range(1, m + 1)])
        self._halt, self._grund, self._ueber, self._neigung = None, None, 0, []
        self.options["weiter"] = False
        print(f"kletter_n1_v0_15_deine_mama WEITER (Halt aufgehoben)", flush=True)

    def _pruefen(self, obs, k: int, q_letzt) -> None:
        """Eingriffe vor Takt k der Folge: Rumpfneigung laufend, Sitz aller Kugeln am Ende jedes Zugs."""
        g = np.asarray(obs["gravity"], float)
        if np.isfinite(g).all() and np.linalg.norm(g) > 0.5:
            self._neigung = (self._neigung + [g / np.linalg.norm(g)])[-WAECHTER_MITTEL:]
            m = np.mean(self._neigung, axis=0)
            soll = self._soll_neigung(min(k, self._laenge - 1))
            abw = float(np.degrees(np.arccos(np.clip(m @ soll / np.linalg.norm(m), -1.0, 1.0))))
            self._ueber = self._ueber + 1 if abw > WAECHTER_SCHWELLE else 0
            if self._ueber >= WAECHTER_DAUER:
                return self._anhalten(q_letzt, f"Rumpfneigung weicht {abw:.0f}° vom Sollverlauf ab (Takt {k})")
        if k == self._uebersprungen:                     # nach „weiter“: dieser Zug gilt als gelungen
            return None
        ende = self._zug_am_ende(k)
        if ende is None:
            return None
        nummer, wiederholung = ende
        glied = _GLIEDER[nummer]
        self._mulden[glied] = np.array(_ZUG_MULDEN[nummer]) + [0.0, 0.0, wiederholung * _SPROSSE_DZ]
        lage = kugeln(_KINEMATIK, np.asarray(obs["q"], float))
        sprosse = 1 if nummer < 6 else wiederholung + 2
        pruefung = {gl: sitzpruefung(lage, self._mulden, gl) for gl in GLIEDER}
        # alle vier Kugeln nah an ihren Mulden (jeweils die drei anderen aufgelegt): gut, auch wenn die drei anderen
        # nicht genau zueinander passen (am echten Roboter ist dieser Rest oft 4–5 mm: v0_9 hielt deshalb grundlos an)
        if all(abstand <= SITZ_SCHWELLE for _, abstand, _ in pruefung.values()):
            return None
        # verfehlt hat das Glied, bei dem die drei anderen am besten auf ihre Mulden passen (kleinster Rest)
        gl = min(GLIEDER, key=lambda g: pruefung[g][2])
        sitzt, abstand, rest = pruefung[gl]
        was = (f"{gl} ({abstand * 1000:.0f} mm daneben)" if rest <= REST_MAX
               else "mehr als ein Glied (keine drei Kugeln passen auf ihre Mulden)")
        versuche = self._versuche.get((nummer, wiederholung), 0)
        if (nummer, wiederholung, versuche) not in self._gewartet:     # erst warten, dann urteilen
            self._gewartet.add((nummer, wiederholung, versuche))
            return self._einschieben([q_letzt] * round(WARTEN_S / 0.02))
        if rest <= REST_MAX and gl == glied and versuche < int(self.options.get("nachgreifen", 0)):
            mulde, R = mulde_im_rumpf(lage, self._mulden, glied)
            d = R @ (lage[glied] - mulde)                # Wandsystem: seitlich, Wand (y), hoch (z)
            schluessel = (nummer, wiederholung, "aufgelegt")
            if d[2] > -AUFGELEGT_UNTER and np.linalg.norm(d[:2]) < AUFGELEGT_NEBEN and schluessel not in self._gewartet:
                self._gewartet.add(schluessel)           # über der Mulde oder nah dran: aufgelegt, hineindrücken
                return self._hineindruecken(nummer, wiederholung, lage, q_letzt, d,
                                            f"Sprosse {sprosse}, Zug {nummer % 6 + 1}")
            return self._nachgreifen(nummer, wiederholung, lage, q_letzt, f"Sprosse {sprosse}, Zug {nummer % 6 + 1}")
        nach = f", nach {versuche} weiteren Versuchen" if versuche else ""
        return self._anhalten(q_letzt, f"Sprosse {sprosse}, Zug {nummer % 6 + 1} ({glied}): nicht in der Mulde: "
                                       f"{was} (auch nach {WARTEN_S:.0f} s Warten{nach})")

    def _hineindruecken(self, nummer: int, wiederholung: int, lage: dict, q_letzt, d, wo: str) -> None:
        """Die Kugel liegt auf dem Griff (über der Mulde oder knapp daneben), es hängt nur noch kein Gewicht darin:
        kein Schwung zurück, nur die Gelenke des Glieds um den Rest zur Mulde (etwas tiefer) in 1 s, dann halten und
        erneut prüfen. Wie beim Nachgreifen gilt die Korrektur danach für denselben Zug jeder weiteren Sprosse."""
        glied = _GLIEDER[nummer]
        mulde, R = mulde_im_rumpf(lage, self._mulden, glied)
        dx = mulde - lage[glied] + R.T @ np.array([0.0, 0.0, -NACHGREIFEN_TIEFER])
        idx = _GLIED_GELENKE[glied]
        grenze = np.radians(NACHGREIFEN_MAX_GRAD)
        korrektur = np.zeros(len(q_letzt))
        korrektur[idx] = np.clip(np.array(_PINV[nummer]) @ dx, -grenze, grenze)
        q0 = np.array(q_letzt, float)
        m = round(1.0 / 0.02)
        print(f"kletter_n1_v0_15_deine_mama HINEINDRÜCKEN, {wo} ({glied}): liegt auf, {d[2] * 1000:+.0f} mm hoch, "
              f"{np.linalg.norm(d[:2]) * 1000:.0f} mm daneben", flush=True)
        self._einschieben([q0 + korrektur * ((k / m) ** 2 * (3 - 2 * k / m)) for k in range(1, m + 1)]
                          + [q0 + korrektur] * round(0.5 / 0.02))
        self._ausklingen(self._einschub_bis, korrektur)
        self._lernen(nummer, wiederholung, korrektur)

    def _nachgreifen(self, nummer: int, wiederholung: int, lage: dict, q_letzt, wo: str) -> None:
        """Die bewegte Kugel hat ihren Griff verfehlt, die drei anderen sitzen. Der Schwung läuft rückwärts (die Kugel
        nimmt den Weg zurück, auf dem sie kam, und hängt wieder im alten Griff; der Körper richtet sich wieder auf),
        dann noch einmal vorwärts — mit den Gelenken des Glieds um die gemessene Abweichung korrigiert (Mulde minus
        Kugel im Rumpfsystem, die drei sitzenden Kugeln geben die Lage zur Wand; mal der vorab berechneten
        Pseudoinversen). Die Korrektur bleibt im Halten und klingt im nächsten Zug aus."""
        glied = _GLIEDER[nummer]
        self._versuche[(nummer, wiederholung)] = self._versuche.get((nummer, wiederholung), 0) + 1
        mulde, R = mulde_im_rumpf(lage, self._mulden, glied)
        dx = mulde - lage[glied] + R.T @ np.array([0.0, 0.0, -NACHGREIFEN_TIEFER])
        idx = _GLIED_GELENKE[glied]
        grenze = np.radians(NACHGREIFEN_MAX_GRAD)
        korrektur = np.zeros(len(q_letzt))
        roh = np.array(_PINV[nummer]) @ dx * NACHGREIFEN_STEIGERUNG ** (self._versuche[(nummer, wiederholung)] - 1)
        korrektur[idx] = roh * min(1.0, grenze / max(np.abs(roh).max(), 1e-9))   # gekappt, Richtung bleibt
        schwung = [np.array(q, float) for q in self._ziele[_SCHWUNG[nummer]:_GRENZEN[nummer]]]
        schwung = [q + (q_letzt - schwung[-1]) for q in schwung]   # mit der Korrektur der vorigen Versuche
        n = len(schwung)
        rueck = schwung[::-1]
        vor = [q + korrektur * min(1.0, (k + 1) / (0.7 * n)) for k, q in enumerate(schwung)]
        print(f"kletter_n1_v0_15_deine_mama NACHGREIFEN ({self._versuche[(nummer, wiederholung)]}. Versuch), {wo} ({glied}): "
              f"Abweichung {np.linalg.norm(dx) * 1000:.0f} mm, Korrektur bis {np.degrees(np.abs(korrektur).max()):.1f}°",
              flush=True)
        self._einschieben(rueck + vor)
        # danach: die gesamte Abweichung vom Plan (alle Versuche) im nächsten Zug ausklingen lassen
        gesamt = vor[-1] - self._folge[self._einschub_bis]
        self._ausklingen(self._einschub_bis, gesamt)
        self._lernen(nummer, wiederholung, korrektur)

    def _lernen(self, nummer: int, wiederholung: int, korrektur) -> None:
        """Der Fehler ist meist systematisch: dieselbe Korrektur gleich in jeder weiteren Sprosse."""
        g5, l2 = _GRENZEN[5], _GRENZEN[11] - _GRENZEN[5]
        spaeter = nummer + 6 if nummer < 6 else nummer
        for r in range(wiederholung + (1 if nummer >= 6 else 0), max(0, (self._laenge - g5) // l2)):
            anfang = g5 + r * l2 + _SCHWUNG[spaeter] - g5
            ende = g5 + r * l2 + _GRENZEN[spaeter] - g5
            n = ende - anfang
            for k in range(n):
                i = self._angleichen + self._einschub + anfang + k
                if i < len(self._folge):
                    self._folge[i] = self._folge[i] + korrektur * min(1.0, (k + 1) / (0.7 * n))
            self._ausklingen(self._angleichen + self._einschub + ende, korrektur)

    def _ausklingen(self, i0: int, abweichung) -> None:
        """Ab i0 eine Abweichung von den Zielen über 3 s ohne Ruck auf null bringen."""
        m = min(round(3.0 / 0.02), len(self._folge) - i0)
        for k in range(max(0, m)):
            self._folge[i0 + k] = self._folge[i0 + k] + abweichung * (1 - (k + 1) / m)

    def _einschieben(self, ziele) -> None:
        """Ziele an dieser Stelle in die Folge einschieben; danach prüft die Bewegung denselben Takt erneut."""
        self._folge[self._i:self._i] = list(ziele)
        self._einschub += len(ziele)
        self._einschub_bis = self._i + len(ziele)

    def step(self, obs):
        if self._halt is not None:             # angehalten: Stellung halten
            return self._halt
        if self._vorlauf > 0:                  # wie beim Lernen: den gemessenen Winkeln folgen, er setzt sich
            self._vorlauf -= 1
            return obs["q"]
        if self._folge is None:
            n = max(1, min(SPROSSEN_MAX, int(self.options["sprossen"])))
            folge = list(self._ziele[:_GRENZEN[5]]) + list(self._ziele[_GRENZEN[5]:_GRENZEN[11]]) * (n - 1)
            self._laenge, self._angleichen = len(folge), 0
            if float(np.abs(obs["q"] - folge[0]).max()) > np.radians(3.0):    # nicht in der Hängestellung: hinführen
                m = round(ANGLEICHEN_S / 0.02)                   # sanft: ohne Ruck an Anfang und Ende
                q0 = np.array(obs["q"], float)
                folge = [q0 + (folge[0] - q0) * ((k / m) ** 2 * (3 - 2 * k / m)) for k in range(1, m + 1)] + folge
                self._angleichen = m
            self._folge = folge
        k = self._i - self._angleichen - self._einschub   # Takt der gelernten Folge (ohne Nachgreifen)
        q_letzt = self._folge[max(0, min(self._i, len(self._folge)) - 1)]
        if self.options.get("eingriffe", True) and 0 <= k <= self._laenge and self._i >= self._einschub_bis:
            self._pruefen(obs, k, q_letzt)
            if self._halt is not None:
                return self._halt
        q = self._folge[min(self._i, len(self._folge) - 1)]   # am Ende die letzte Stellung halten
        self._i += 1
        return q
